<?php
declare(strict_types=1);
final class Schema19LifecycleProvenanceTest extends WP_UnitTestCase{
 protected function setUp():void{parent::setUp();DigiForge\Core\Activator::activate();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 public function testSchema19CreatesProvenanceAndExplicitClosureState():void{global $wpdb;self::assertSame(19,(int)get_option('digiforge_db_schema_version'));self::assertSame(DigiForge\Database\Tables::pod_authorization_bindings(),$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',DigiForge\Database\Tables::pod_authorization_bindings())));$columns=$wpdb->get_col('DESC '.DigiForge\Database\Tables::pod_lifecycle_closures(),0);self::assertContains('external_execution_state',$columns);}
 public function testHistoryUsesProspectiveBindingBeforeClosure():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','v19-history-auth');$nonce='v19_history_nonce_123456789012345';$nh=hash('sha256',$nonce);$ph=hash('sha256','v19-history-package');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_packages(),['order_id'=>1,'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','v19-ready'),'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id(),'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]);$pid=(int)$wpdb->insert_id;self::assertTrue(DigiForge\POD\ExecutionNonceLedger::consume($nonce,$auth,get_current_user_id()));$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid,'package_hash'=>$ph,'authorization_hash'=>$auth,'nonce_hash'=>$nh,'bound_by'=>get_current_user_id(),'bound_at'=>$now]);$h=(new DigiForge\POD\ProductionLifecycleHistoryReadModel())->project($auth);self::assertSame('CONSUMED_AWAITING_OUTCOME',$h['lifecycle_state']);self::assertSame($pid,(int)$h['authorization_package']['id']);self::assertSame($auth,$h['authorization_binding']['authorization_hash']);}
 public function testClosureRejectsConflictingProspectiveProvenance():void{global $wpdb;$now=current_time('mysql',true);$auth=hash('sha256','v19-conflict-auth');$nonce='v19_conflict_nonce_12345678901234';$nh=hash('sha256',$nonce);$ph=hash('sha256','v19-package-a');$wpdb->insert(DigiForge\Database\Tables::pod_authorization_packages(),['order_id'=>1,'render_evidence_id'=>1,'provider_mapping_id'=>1,'ownership_mapping_id'=>1,'readiness_hash'=>hash('sha256','v19-r'),'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id(),'approved_at'=>$now,'external_execution_authorized'=>0,'external_execution_performed'=>0,'created_at'=>$now]);$pid=(int)$wpdb->insert_id;self::assertTrue(DigiForge\POD\ExecutionNonceLedger::consume($nonce,$auth,get_current_user_id()));$wpdb->insert(DigiForge\Database\Tables::pod_authorization_bindings(),['package_id'=>$pid+999,'package_hash'=>hash('sha256','wrong'),'authorization_hash'=>$auth,'nonce_hash'=>$nh,'bound_by'=>get_current_user_id(),'bound_at'=>$now]);$fh=hash('sha256','v19-f');$wpdb->insert(DigiForge\Database\Tables::pod_execution_failures(),['action'=>'X','evidence_hash'=>hash('sha256','v19-e'),'authorization_hash'=>$auth,'nonce_hash'=>$nh,'failure_category'=>'adapter_error','failure_code'=>'timeout','executed_by'=>get_current_user_id(),'recorded_at'=>$now,'failure_hash'=>$fh,'created_at'=>$now]);$projection=(new DigiForge\POD\ConsumedPermitOutcomeReadModel())->project($auth);$closure=(new DigiForge\POD\ProductionLifecycleClosure())->close(['id'=>$pid,'package_hash'=>$ph,'state'=>'APPROVED_PACKAGE','approved_by'=>get_current_user_id()],$projection,get_current_user_id());$saved=DigiForge\POD\ProductionLifecycleClosureRepository::save($closure);self::assertWPError($saved);self::assertSame('production_closure_provenance_conflict',$saved->get_error_code());}
}
